import { Request, Response } from 'express';
import mongoose from 'mongoose';
import { getBucket } from '../config/database';
import { Readable } from 'stream';

// رفع ملف إلى GridFS
export async function uploadFile(req: Request, res: Response): Promise<void> {
  try {
    if (!req.file) {
      res.status(400).json({ success: false, message: 'لم يتم رفع أي ملف' });
      return;
    }

    const bucket = getBucket();
    const fileId = new mongoose.Types.ObjectId();

    const uploadStream = bucket.openUploadStreamWithId(fileId, req.file.originalname, {
      contentType: req.file.mimetype,
      metadata: {
        originalName: req.file.originalname,
        size: req.file.size,
      },
    });

    const bufferStream = new Readable();
    bufferStream.push(req.file.buffer);
    bufferStream.push(null);

    bufferStream
      .pipe(uploadStream)
      .on('error', (error) => {
        console.error('خطأ في رفع الملف:', error);
        res.status(500).json({ success: false, message: 'فشل رفع الملف' });
      })
      .on('finish', () => {
        res.status(200).json({
          success: true,
          data: {
            fileId: fileId.toString(),
            fileName: req.file!.originalname,
            fileSize: req.file!.size,
          },
        });
      });
  } catch (error) {
    console.error('خطأ:', error);
    res.status(500).json({ success: false, message: 'خطأ داخلي' });
  }
}

// تحميل ملف من GridFS
export async function downloadFile(req: Request, res: Response): Promise<void> {
  try {
    const { id } = req.params;
    const bucket = getBucket();
    const fileId = new mongoose.Types.ObjectId(id);

    const files = await bucket.find({ _id: fileId }).toArray();
    if (files.length === 0) {
      res.status(404).json({ success: false, message: 'الملف غير موجود' });
      return;
    }

    const file = files[0];
    res.set('Content-Type', file.contentType || 'application/octet-stream');
    res.set('Content-Disposition', `inline; filename="${encodeURIComponent(file.filename)}"`);

    bucket
      .openDownloadStream(fileId)
      .on('error', (error) => {
        console.error('خطأ في تحميل الملف:', error);
        res.status(500).json({ success: false, message: 'فشل تحميل الملف' });
      })
      .pipe(res);
  } catch (error) {
    console.error('خطأ:', error);
    res.status(500).json({ success: false, message: 'خطأ داخلي' });
  }
}

// حذف ملف من GridFS
export async function deleteFile(fileId: string): Promise<void> {
  try {
    const bucket = getBucket();
    await bucket.delete(new mongoose.Types.ObjectId(fileId));
  } catch (error) {
    console.error('تحذير: تعذر حذف الملف من GridFS:', fileId, error);
  }
}

import multer from 'multer';

// تخزين الملفات في الذاكرة مؤقتاً قبل رفعها إلى GridFS
const storage = multer.memoryStorage();

export const upload = multer({
