// ============================================
// مسار التنبيهات (Notifications)
// ============================================
router.get('/notifications', async (_req, res) => {
  try {
    const notifications: any[] = [];
    const today = new Date().toISOString().split('T')[0];
    const now = new Date();
    const in7Days = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
    const in30Days = new Date(now.getTime() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];

    // 1. الجلسات القادمة
    const sessions = await CaseSession.find({ sessionDate: { $gte: today } })
      .populate({
        path: 'caseId',
        select: 'caseNumber caseYear customerId',
        populate: { path: 'customerId', select: 'name' },
      })
      .populate('courtId', 'name')
      .sort({ sessionDate: 1 });

    for (const s of sessions) {
      const daysLeft = s.sessionDate
        ? Math.ceil((new Date(s.sessionDate).getTime() - now.getTime()) / (1000 * 60 * 60 * 24))
        : 0;

      let urgency: 'high' | 'medium' | 'low' = 'low';
      if (s.sessionDate <= in7Days) urgency = 'high';
      else if (s.sessionDate <= in30Days) urgency = 'medium';

      const customerName = (s.caseId as any)?.customerId?.name || '';

      notifications.push({
        id: s._id.toString(),
        type: 'session',
        title: `جلسة محكمة - ${(s.caseId as any)?.caseNumber || ''}`,
        description: s.subject || '',
        date: s.sessionDate,
        caseNumber: (s.caseId as any)?.caseNumber,
        courtName: (s.courtId as any)?.name,
        customerName,
        daysLeft,
        urgency,
      });
    }

    // 2. الإعلانات ذات الجلسات القادمة خلال أسبوع
    const in1Day = new Date(now.getTime() + 2 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
    const in3Days = new Date(now.getTime() + 3 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];

    const announcements = await CaseAnnouncement.find({
      sessionDate: { $gte: today, $lte: in7Days, $ne: '' },
    })
      .populate({
        path: 'caseId',
        select: 'caseNumber caseYear customerId',
        populate: { path: 'customerId', select: 'name' },
      })
      .populate('courtId', 'name')
      .populate('announcementTypeId', 'name')
      .sort({ sessionDate: 1 });

    for (const a of announcements) {
      const daysLeft = a.sessionDate
        ? Math.ceil((new Date(a.sessionDate).getTime() - now.getTime()) / (1000 * 60 * 60 * 24))
        : 0;

      let urgency: 'high' | 'medium' | 'low' = 'low';
      if (a.sessionDate <= in1Day) urgency = 'high';
      else if (a.sessionDate <= in3Days) urgency = 'medium';
      else urgency = 'low';

      const customerName = (a.caseId as any)?.customerId?.name || '';
      const announcementTypeName = (a.announcementTypeId as any)?.name || '';

      notifications.push({
        id: a._id.toString(),
        type: 'announcement',
        title: `إعلان ${announcementTypeName} رقم ${a.announcementNumber} - ${(a.caseId as any)?.caseNumber || ''}`,
        description: a.subject || '',
        date: a.sessionDate || '',
        caseNumber: (a.caseId as any)?.caseNumber,
        courtName: (a.courtId as any)?.name,
        customerName,
        recipientName: a.recipientName || '',
        bailiffName: a.bailiffName || '',
        announcementNumber: a.announcementNumber || '',
        announcementTypeName,
        deliveryDate: a.deliveryDate || '',
        receiptDate: a.receiptDate || '',
        daysLeft,
        urgency,
      });
    }

    // 3. المهام القادمة غير المكتملة
    const tasks = await Task.find({
      status: { $in: ['pending', 'in_progress'] },
      dueDate: { $gte: today, $ne: '' },
    })
      .populate('customerId', 'name')
      .populate('caseId', 'caseNumber caseYear')
      .sort({ dueDate: 1 });

    for (const t of tasks) {
      let urgency: 'high' | 'medium' | 'low' = t.priority || 'medium';
      if (t.dueDate <= in7Days) urgency = 'high';
      else if (t.dueDate <= in30Days) urgency = 'medium';

      notifications.push({
        id: t._id.toString(),
        type: 'task',
        title: `مهمة - ${t.title}`,
        description: t.description || '',
        date: t.dueDate,
        caseNumber: (t.caseId as any)?.caseNumber,
        urgency,
      });
    }

    res.json({ success: true, data: notifications });
  } catch (err) { res.status(500).json({ success: false, message: (err as Error).message }); }
});

